'use strict';

function parseAmount(raw) {
  if (raw == null) return 0;
  let s = String(raw).trim();
  if (!s) return 0;

  // Strip leading currency symbol
  s = s.replace(/^\$/, '').trim();

  // Extract sign
  let sign = 1;
  if (s.startsWith('-')) { sign = -1; s = s.slice(1); }
  else if (s.startsWith('+')) { s = s.slice(1); }

  // Locale-normalize: the feed mixes en-US (dot decimal) and de-DE (comma decimal).
  // Rule: when both separators appear, the LAST one is the decimal point.
  const lastDot = s.lastIndexOf('.');
  const lastComma = s.lastIndexOf(',');

  let normalized;
  if (lastDot !== -1 && lastComma !== -1) {
    if (lastDot > lastComma) {
      // en-US: "1,234.56" → strip thousand-commas
      normalized = s.replace(/,/g, '');
    } else {
      // de-DE: "1.234,56" → strip thousand-dots, swap decimal comma
      normalized = s.replace(/\./g, '').replace(',', '.');
    }
  } else if (lastComma !== -1) {
    // Only comma present → de-DE decimal: "99,90"
    normalized = s.replace(',', '.');
  } else {
    normalized = s;
  }

  const n = Number(normalized);
  if (!isFinite(n) || isNaN(n)) return 0;
  return sign * n;
}

function sumAmounts(rows) {
  if (!rows || rows.length === 0) return 0;
  let total = 0;
  for (const row of rows) {
    total += parseAmount(row.amount);
  }
  return Math.round(total * 100) / 100;
}

module.exports = { sumAmounts };

